INSERT INTO articles (slug,title,teaser,body,category,topic,region,kind,author,image,source_name,source_url,status,published_at,updated_at,meta_title,meta_description,focus_keyword,keywords,image_alt,image_prompt,faq,service) VALUES ('scale-up-fonds-oesterreich-500-millionen-dachfonds-startups-aws','Scale-up-Fonds Österreich: 500 Mio. Euro für Start-ups','Der Bund gibt den Startschuss für einen rot-weiß-roten Scale-up-Fonds: Rund 500 Millionen Euro sollen über Risikokapitalfonds in wachsende heimische Firmen fließen.','Der neue **Scale-up-Fonds** soll heimischen Start-ups und schnell wachsenden Unternehmen den nächsten großen Finanzierungsschritt in Österreich ermöglichen. Wirtschaftsminister Wolfgang Hattmannsdorfer und Staatssekretärin Elisabeth Zehetner haben am Samstag den Startschuss für den sogenannten rot-weiß-roten Scale-up-Fonds gegeben. Er ist als Dachfonds angelegt und soll ein Volumen von rund 500 Millionen Euro erreichen.

## So funktioniert der Scale-up-Fonds

Ein Dachfonds investiert nicht direkt in einzelne Firmen, sondern in andere Fonds. Im konkreten Fall soll das Geld an spezialisierte Risikokapital- und Wachstumsfonds gehen, die ihrerseits Beteiligungen an Unternehmen eingehen. Über die gesamte Laufzeit sollen auf diesem Weg mindestens 100 Millionen Euro bei Unternehmen in Österreich ankommen.

Der Bund beteiligt sich über die Förderbank aws (Austria Wirtschaftsservice) als Ankerinvestor, bleibt dabei aber in der Minderheit. Laut Ministerium fließen insgesamt bis zu 100 Millionen Euro an Bundesmitteln:

- 75 Millionen Euro stehen bereits zum Start zur Verfügung.
- Weitere bis zu 25 Millionen Euro können folgen, abhängig davon, wie gut die Suche nach privaten Geldgebern vorankommt.
- Angestrebt wird, dass jeder Euro des Bundes rund fünf Euro Fondsvolumen auslöst.

Zehetner betonte, dass die öffentliche Hand keine Sonderrolle einnimmt: „Der Bund investiert zu denselben Bedingungen wie private Kapitalgeber.“

## Zielgruppe: Start-ups, Spin-offs und Wachstumsfirmen

Im Fokus stehen junge Unternehmen, die die Gründungsphase hinter sich haben und nun deutlich mehr Kapital brauchen, etwa für eine erste Produktion oder den Schritt auf internationale Märkte. Genannt werden neben Start-ups und Scale-ups auch Ausgründungen aus Hochschulen und Forschungseinrichtungen sowie allgemein wachstumsstarke Betriebe. Ein Schwerpunkt liegt auf Schlüsseltechnologien, die in der Industriestrategie der Regierung festgelegt sind.

Hintergrund ist ein bekanntes Problem der heimischen Gründerszene: Während die ersten Finanzierungsrunden oft noch im Inland gelingen, fehlt für größere Wachstumsrunden häufig das Kapital. Hattmannsdorfer stellt den Fonds deshalb als Baustein zur Stärkung des österreichischen Kapitalmarkts dar. Das Umfeld ist schwierig: Die heimische Wirtschaft ist zuletzt nur schwach gewachsen, wie die [WIFO-Zahlen zum BIP im 3. Quartal 2026](/artikel/bip-oesterreich-3-quartal-2026-wifo-wachstum-0-2-prozent) zeigen.

## Zeitplan bis zu den ersten Investments

Bis tatsächlich Geld bei Unternehmen ankommt, wird es noch dauern. Das Ministerium nennt folgende Schritte:

1. Im ersten Quartal 2027 wählt die aws in einer Ausschreibung das Fondsmanagement aus.
2. Ab Mitte 2027 soll privates Kapital eingeworben werden.
3. Erste verbindliche Kapitalzusagen sind je nach Fortschritt ab Ende 2027 möglich, danach starten die Investitionen.

## Reaktionen aus der Wirtschaft

Die Junge Wirtschaft in der Wirtschaftskammer begrüßte den Dachfonds und sieht darin auch eine Stärkung des heimischen Risikokapitalmarkts. Entscheidend sei aus ihrer Sicht, wie viel zusätzliches privates Geld mobilisiert werden kann. Die Organisation wünscht sich, dass sich auch institutionelle Anleger wie Pensionskassen und Versicherungen beteiligen, und drängt auf einen raschen Start. Bundesgeschäftsführer Lukas Sprenger brachte es knapp auf den Punkt: „Jetzt zählt die Umsetzung.“

Auch die Industriellenvereinigung und der Wirtschaftsbund äußerten sich am Samstag positiv zur Umsetzung des Fonds.

## Was Gründerinnen und Gründer jetzt wissen sollten

Direkt beim Scale-up-Fonds kann man sich nicht um Geld bewerben, da er ausschließlich in andere Fonds investiert. Für Unternehmen führt der Weg künftig über jene Risikokapital- und Wachstumsfonds, an denen sich der Dachfonds beteiligt. Wer in den kommenden Jahren eine größere Finanzierungsrunde plant, sollte daher die Auswahl der Zielfonds ab 2027 im Blick behalten. Wer erst am Anfang steht, findet in unserem Überblick zum [e.U. gründen](/artikel/eu-eingetragener-unternehmer-firmenbuch-vorteile) die wichtigsten Schritte zur eigenen Firma.','wirtschaft','Gründen',NULL,'news','Presseinfo Redaktion','/assets/img/artikel/scale-up-fonds-oesterreich-500-millionen-dachfonds-startups-aws.webp','Bundesministerium für Wirtschaft, Energie und Tourismus (APA-OTS)','https://www.ots.at/presseaussendung/OTS_20261121_OTS0003/hattmannsdorfer-und-zehetner-setzen-industriestrategie-um-startschuss-fuer-rot-weiss-roten-scale-up-fonds','published','2026-11-22T11:50:00.000Z','2026-11-22T13:27:32.167Z','Scale-up-Fonds: 500 Mio. Euro für Start-ups','Scale-up-Fonds Österreich: Der Bund startet einen Dachfonds mit rund 500 Mio. Euro für Start-ups und Scale-ups. Ablauf, Zeitplan und Ziele im Überblick.','Scale-up-Fonds','["Scale-up-Fonds","Dachfonds Österreich","Start-up Finanzierung Österreich","Wachstumskapital Start-ups","aws Dachfonds","Venture Capital Österreich","rot-weiß-roter Scale-up-Fonds","Industriestrategie Österreich","Scale-ups Finanzierungsrunde"]','Scale-up-Fonds Österreich: Junges Technologieunternehmen in einer Werkhalle mit Prototypen','Modern open-plan tech startup workshop in a converted brick industrial hall in Austria, prototype hardware and small production machines on workbenches, laptops, team members seen from behind or at a distance, warm daylight through tall factory windows, no text, no logos, no readable signs','[{"q":"Wie groß ist der Scale-up-Fonds?","a":"Angestrebt ist ein Fondsvolumen von rund 500 Millionen Euro, davon bis zu 100 Millionen Euro vom Bund über die aws."},{"q":"Können sich Start-ups direkt beim Fonds bewerben?","a":"Nein. Der Dachfonds investiert in Risikokapital- und Wachstumsfonds, die ihrerseits in Unternehmen investieren."},{"q":"Wann fließt das erste Geld?","a":"Das Fondsmanagement wird im ersten Quartal 2027 ausgewählt, erste verbindliche Zusagen sind ab Ende 2027 möglich."}]',0) ON CONFLICT(slug) DO UPDATE SET title=excluded.title, teaser=excluded.teaser, body=excluded.body, category=excluded.category, topic=excluded.topic, region=excluded.region, kind=excluded.kind, author=excluded.author, source_name=excluded.source_name, source_url=excluded.source_url, status=excluded.status, published_at=excluded.published_at, updated_at=excluded.updated_at, meta_title=excluded.meta_title, meta_description=excluded.meta_description, focus_keyword=excluded.focus_keyword, keywords=excluded.keywords, image_alt=excluded.image_alt, image_prompt=excluded.image_prompt, faq=excluded.faq, service=excluded.service, image=COALESCE(excluded.image, articles.image);
